  iv_save_time: { tr:'Kaydet', en:'Save', ru:'Сохранить', kk:'Сақтау', ky:'Сактоо', uz:'Saqlash', tk:'Ýatda sakla', de:'Sichern', th:'บันทึก', fa:'ذخیره' },
  iv_rule_days: { tr:'En fazla 3 farklı gün ekleyebilirsiniz.', en:'You can add at most 3 different days.', ru:'Можно добавить не более 3 разных дней.', kk:'Ең көбі 3 түрлі күн қоса аласыз.', ky:'Эң көбү 3 башка күн коё аласыз.', uz:'Ko‘pi bilan 3 xil kun qo‘sha olasiz.', tk:'Iň köpi 3 dürli gün goşup bilersiňiz.', de:'Sie können höchstens 3 verschiedene Tage hinzufügen.', th:'เพิ่มได้สูงสุด 3 วันที่ต่างกัน', fa:'حداکثر ۳ روز مختلف می‌توانید اضافه کنید.' },
  iv_rule_times: { tr:'Bir gün için en fazla 3 saat ekleyebilirsiniz.', en:'You can add at most 3 times per day.', ru:'Не более 3 времён в день.', kk:'Бір күнге ең көбі 3 уақыт.', ky:'Бир күнгө эң көбү 3 убакыт.', uz:'Bir kunga ko‘pi bilan 3 vaqt.', tk:'Bir güne iň köpi 3 wagt.', de:'Höchstens 3 Zeiten pro Tag.', th:'เพิ่มได้สูงสุด 3 ช่วงต่อวัน', fa:'حداکثر ۳ زمان در روز.' },
  iv_progress: { tr:'{days}/3 gün · bu gün {times}/3 saat', en:'{days}/3 days · this day {times}/3 times', ru:'{days}/3 дн. · сегодня {times}/3 врем.', kk:'{days}/3 күн · бұл күн {times}/3 уақыт', ky:'{days}/3 күн · бул күн {times}/3 убакыт', uz:'{days}/3 kun · bu kun {times}/3 vaqt', tk:'{days}/3 gün · bu gün {times}/3 wagt', de:'{days}/3 Tage · heute {times}/3 Zeiten', th:'{days}/3 วัน · วันนี้ {times}/3 เวลา', fa:'{days}/3 روز · امروز {times}/3 زمان' },
  iv_conflict: { tr:'Seçtiğiniz saatlerden biri başka bir aday için dolu. Lütfen değiştirin.', en:'One of the selected times is already taken by another candidate. Please change it.', ru:'Одно из выбранных времён уже занято другим кандидатом. Измените, пожалуйста.', kk:'Таңдаған уақыттарыңыздың бірі басқа үміткерге толы. Өзгертіңіз.', ky:'Тандаган убакыттарыңыздын бири башка талапкерге толгон. Өзгөртүңүз.', uz:'Tanlagan vaqtlaringizdan biri boshqa nomzodga band. Iltimos, o‘zgartiring.', tk:'Saýlan wagtlaryňyzyň biri başga dalaşgäre band. Üýtgediň.', de:'Eine der gewählten Zeiten ist bereits von einem anderen Bewerber belegt. Bitte ändern.', th:'เวลาที่เลือกหนึ่งช่วงถูกใช้โดยผู้สมัครอื่นแล้ว โปรดเปลี่ยน', fa:'یکی از زمان‌های انتخابی قبلاً برای داوطلب دیگری رزرو شده. لطفاً تغییر دهید.' },
  iv_localtime: { tr:'Saatler kendi saat diliminizde gösterilir.', en:'Times are shown in your own time zone.', ru:'Время показано в вашем часовом поясе.', kk:'Уақыт сіздің сағаттық белдеуіңізде көрсетіледі.', de:'Zeiten werden in Ihrer Zeitzone angezeigt.', th:'แสดงเวลาตามเขตเวลาของคุณ', uz:'Vaqtlar oʻz vaqt mintaqangizda koʻrsatiladi.', fa:'زمان‌ها در منطقه زمانی شما نمایش داده می‌شود.', ky:'Убакыт сиздин убакыт алкагыңызда көрсөтүлөт.', tk:'Wagtlar öz wagt guşagyňyzda görkezilýär.' },
  iv_congrats_title: { tr:'Tebrikler!', en:'Congratulations!', ru:'Поздравляем!', kk:'Құттықтаймыз!', de:'Glückwunsch!', th:'ยินดีด้วย!', uz:'Tabriklaymiz!', fa:'تبریک!', ky:'Куттуктайбыз!', tk:'Gutlaýarys!' },
  iv_congrats: { tr:'Lütfen seçtiğiniz tarih ve saatte mülakat için hazır bulunun. Katılmamanız durumunda diğer adaylarla devam edilir ve bu alım dönemi için hakkınızı kaybedersiniz.', en:'Please be ready for the interview at your chosen date and time. If you don’t attend, we’ll proceed with other candidates and you’ll lose your chance for this recruitment period.', ru:'Пожалуйста, будьте готовы к собеседованию в выбранные дату и время. В случае неявки мы продолжим с другими кандидатами, и вы потеряете шанс на этот период набора.', kk:'Таңдаған күн мен уақытта сұхбатқа дайын болыңыз. Қатыспасаңыз, басқа үміткерлермен жалғастырамыз және осы кезеңдегі мүмкіндігіңізді жоғалтасыз.', de:'Bitte seien Sie zum gewählten Termin bereit. Bei Nichterscheinen fahren wir mit anderen Bewerbern fort und Sie verlieren Ihre Chance für diesen Zeitraum.', th:'โปรดเตรียมพร้อมสำหรับการสัมภาษณ์ตามวันและเวลาที่เลือก หากไม่เข้าร่วม เราจะดำเนินการกับผู้สมัครรายอื่นและคุณจะเสียโอกาสในรอบรับสมัครนี้', uz:'Tanlagan kun va vaqtingizda suhbatga tayyor bo‘ling. Qatnashmasangiz, boshqa nomzodlar bilan davom etamiz va bu qabul davri uchun imkoniyatingizni yo‘qotasiz.', fa:'لطفاً در تاریخ و ساعت انتخابی برای مصاحبه آماده باشید. در صورت عدم حضور، با داوطلبان دیگر ادامه می‌دهیم و فرصت این دوره را از دست می‌دهید.', ky:'Тандаган күнү жана убакта маекке даяр болуңуз. Катышпасаңыз, башка талапкерлер менен улантабыз жана бул кабыл алуу мезгилиндеги мүмкүнчүлүгүңүздү жоготосуз.', tk:'Saýlan güatyňyzda söhbete taýýar boluň. Gatnaşmasaňyz, beýleki dalaşgärler bilen dowam ederis we bu kabul döwri üçin mümkinçiligiňizi ýitirersiňiz.' },
