  doc_choose_pdf: { tr:'📄 PDF / Dosya', en:'📄 PDF / File', ru:'📄 PDF / Файл', kk:'📄 PDF / Файл', de:'📄 PDF / Datei', th:'📄 PDF / ไฟล์', uz:'📄 PDF / Fayl', fa:'📄 PDF / فایل', ky:'📄 PDF / Файл', tk:'📄 PDF / Faýl' },
  reupload_confirm: { tr:'Bu belge silinecek ve adaydan yeniden yüklemesi istenecek. Devam edilsin mi?', en:'This document will be removed and the candidate asked to re-upload. Continue?', ru:'Этот документ будет удалён, и кандидата попросят загрузить заново. Продолжить?', kk:'Бұл құжат жойылып, үміткерден қайта жүктеу сұралады. Жалғастырасыз ба?', ky:'Бул документ өчүрүлүп, талапкерден кайра жүктөө суралат. Уланталбы?', uz:'Bu hujjat o‘chiriladi va nomzoddan qayta yuklash so‘raladi. Davom etilsinmi?', tk:'Bu resminama pozulyp, dalaşgärden gaýtadan ýüklemek soralar. Dowam edilsinmi?', de:'Dieses Dokument wird gelöscht und der Bewerber zum erneuten Hochladen aufgefordert. Fortfahren?', th:'เอกสารนี้จะถูกลบและขอให้ผู้สมัครอัปโหลดใหม่ ดำเนินการต่อหรือไม่?', fa:'این مدرک حذف و از داوطلب خواسته می‌شود دوباره بارگذاری کند. ادامه می‌دهید؟' },
  notif_document: { tr:'Aday yeni belge yükledi.', en:'A candidate uploaded new documents.', ru:'Кандидат загрузил новые документы.', kk:'Үміткер жаңа құжат жүктеді.', de:'Ein Bewerber hat neue Dokumente hochgeladen.', th:'ผู้สมัครอัปโหลดเอกสารใหม่', uz:'Nomzod yangi hujjat yukladi.', fa:'داوطلب مدارک جدید بارگذاری کرد.', ky:'Талапкер жаңы документ жүктөдү.', tk:'Dalaşgär täze resminama ýükledi.' },
  notif_document_for_you: { tr:'Acenten sizin için bir belge gönderdi.', en:'Your agency sent you a document.', ru:'Агентство отправило вам документ.', kk:'Агенттік сізге құжат жіберді.', de:'Ihre Agentur hat Ihnen ein Dokument gesendet.', th:'เอเจนซี่ส่งเอกสารให้คุณ', uz:'Agentlik sizga hujjat yubordi.', fa:'آژانس برای شما مدرک فرستاد.', ky:'Агенттик сизге документ жөнөттү.', tk:'Agentlik size resminama iberdi.' },
