  privacy_link: { tr:'KVKK Aydınlatma Metni', en:'Privacy Notice', ru:'Уведомление о конфиденциальности', kk:'Құпиялылық хабарламасы', de:'Datenschutzhinweis', th:'ประกาศความเป็นส่วนตัว', uz:'Maxfiylik bildirishnomasi', fa:'بیانیه حریم خصوصی', ky:'Купуялык эскертүүсү', tk:'Gizlinlik habarnamasy' },
