  pdf_choose: { tr:'İndirme seçeneğini seç', en:'Choose a download option', ru:'Выберите вариант загрузки', kk:'Жүктеу нұсқасын таңдаңыз', de:'Download-Option wählen', th:'เลือกตัวเลือกการดาวน์โหลด', uz:'Yuklab olish variantini tanlang', fa:'یک گزینه دانلود را انتخاب کنید', ky:'Жүктөө вариантын тандаңыз', tk:'Göçürip almak görnüşini saýlaň' },
