  flight_arrive_kicker: { tr:'Zorunlu', en:'Required', ru:'Обязательно', kk:'Міндетті', de:'Pflicht', th:'จำเป็น', uz:'Majburiy', fa:'الزامی', ky:'Милдеттүү', tk:'Hökmany' },
  flight_arrive_notice_title: { tr:'İniş günü ve saati', en:'Landing date and time', ru:'Дата и время прилёта', kk:'Қону күні мен уақыты', de:'Ankunftsdatum und -zeit', th:'วันและเวลาลงจอด', uz:'Qo‘nish kuni va vaqti', fa:'تاریخ و ساعت فرود', ky:'Конгон күн жана саат', tk:'Iniýän gün we sagat' },
  flight_arrive_notice: { tr:'Personel varış hatırlatmaları ve Varışlar listesi bu alandan çalışır. Karşılama planı için iniş günü ve saati zorunludur; boşsa uçak bileti yüklenemez.', en:'Staff arrival reminders and the Arrivals list use this field. Landing date and time are required for pickup planning; the ticket cannot be uploaded without them.', ru:'Напоминания о прилёте и список прибытий берутся отсюда. Дата и время посадки обязательны — без них билет не загрузить.', kk:'Қарсы алу еске салғыштары мен Келулер тізімі осы жерден. Қону күні мен уақыты міндетті — бос болса билет жүктелмейді.', de:'Ankunftserinnerungen und die Ankunftsliste nutzen dieses Feld. Datum und Uhrzeit der Landung sind Pflicht — ohne sie kein Ticket-Upload.', th:'การเตือนถึงและรายการมาถึงใช้ช่องนี้ ต้องระบุวันและเวลาลงจอด จึงจะอัปโหลดตั๋วได้', uz:'Xodim kelishi eslatmalari va Kelishlar ro‘yxati shu maydondan. Qo‘nish kuni va vaqti majburiy — bo‘sh bo‘lsa chipta yuklanmaydi.', fa:'یادآوری ورود پرسنل و فهرست ورود از این فیلد است. تاریخ و ساعت فرود الزامی است؛ بدون آن بلیط بارگذاری نمی‌شود.', ky:'Келишим эскертмелери жана Келишимдер тизмеси ушул талаадан. Конгон күн жана саат милдеттүү — бош болсо билет жүктөлбөйт.', tk:'Işgär gelýän ýatladyşlar we Gelişler sanawy şu meýdandan. Iniş güni we sagaty hökmany — boş bolsa bilet ýükläp bolmaýar.' },
  flight_arrive_label: { tr:'İniş tarihi', en:'Landing date', ru:'Дата прилёта', kk:'Қону күні', de:'Ankunftsdatum', th:'วันลงจอด', uz:'Qo‘nish sanasi', fa:'تاریخ فرود', ky:'Конгон күн', tk:'Iniş senesi' },
  flight_arrive_time_label: { tr:'İniş saati', en:'Landing time', ru:'Время прилёта', kk:'Қону уақыты', de:'Ankunftszeit', th:'เวลาลงจอด', uz:'Qo‘nish vaqti', fa:'ساعت فرود', ky:'Конгон саат', tk:'Iniş sagaty' },
  flight_arrive_time_pick: { tr:'Saat seç', en:'Pick time', ru:'Выбрать время', kk:'Уақытты таңдау', de:'Uhrzeit wählen', th:'เลือกเวลา', uz:'Vaqtni tanlash', fa:'انتخاب ساعت', ky:'Саатты тандоо', tk:'Sagat saýla' },
  flight_arrive_required: { tr:'İniş tarihi ve saati zorunludur. Boşsa uçak bileti yüklenemez.', en:'Landing date and time are required. The ticket cannot be uploaded without them.', ru:'Дата и время прилёта обязательны. Без них билет не загрузить.', kk:'Қону күні мен уақыты міндетті. Бос болса билет жүктелмейді.', de:'Ankunftsdatum und -zeit sind Pflicht. Ohne sie kein Ticket-Upload.', th:'ต้องระบุวันและเวลาลงจอด จึงจะอัปโหลดตั๋วได้', uz:'Qo‘nish kuni va vaqti majburiy. Bo‘sh bo‘lsa chipta yuklanmaydi.', fa:'تاریخ و ساعت فرود الزامی است. بدون آن بلیط بارگذاری نمی‌شود.', ky:'Конгон күн жана саат милдеттүү. Бош болсо билет жүктөлбөйт.', tk:'Iniş güni we sagaty hökmany. Boş bolsa bilet ýükläp bolmaýar.' },
  flight_arrive_required_before_send: { tr:'Uçak biletini göndermeden önce iniş günü ve saatini girin. Varış hatırlatmaları bu alana bağlıdır.', en:'Enter landing date and time before sending the ticket. Arrival reminders depend on this field.', ru:'Укажите дату и время прилёта до отправки билета.', kk:'Билетті жібермес бұрын қону күні мен уақытын енгізіңіз.', de:'Ankunftsdatum und -zeit vor dem Senden des Tickets eingeben.', th:'ใส่วันและเวลาลงจอดก่อนส่งตั๋ว', uz:'Chiptani yuborishdan oldin qo‘nish kuni va vaqtini kiriting.', fa:'قبل از ارسال بلیط تاریخ و ساعت فرود را وارد کنید.', ky:'Билетти жөнөтүүдөн мурун конгон күн жана саатты киргизиңиз.', tk:'Bileti ibermezden öň iniş güni we sagatyny giriziň.' },
